package org.sleepwell.app;
import android.content.*;import java.time.*;import java.util.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
/** Real private SQLite, portable JSON and injected scheduling. No AlarmManager or runtime. */
public final class SunriseStorageTest {
    final SunriseSchedule solar=new SunriseSchedule(40.72,-74.02,-30,true);
    @Test public void legacyAlarmAndSkipRemainUnchangedAndCoordinatesNeverBecomeDefaults()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){Alarm legacy=f.load();assertFalse(legacy.json().has("solar"));String before=legacy.json().toString();assertEquals(before,Alarm.read(legacy.json()).json().toString());AlarmSkip skip=new AlarmSkip("11111111-1111-4111-8111-111111111111",LocalDate.of(2026,10,23),6,30,legacy.days,"UTC");JSONObject raw=AlarmSkipJson.encode(skip);assertEquals(1,raw.getInt("version"));assertEquals(7,raw.length());assertEquals(raw.toString(),AlarmSkipJson.encode(AlarmSkipJson.decode(raw)).toString());legacy.solar=solar;Alarm copy=new AlarmDefaults(legacy).create(44);assertNull(copy.solar);assertFalse(AlarmDefaultsJson.encode(new AlarmDefaults(legacy)).contains("latitude"));}}
    @Test public void strictSolarMetadataAndTypedSkipCannotSilentlyBroadenRestore()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){JSONObject raw=f.load().json();JSONObject settings=SunriseScheduleJson.encode(solar);raw.put("solar",settings);assertFalse(Alarm.read(raw).solarInvalid);for(Object wrong:new Object[]{JSONObject.NULL,"40.72",true}){JSONObject invalid=new JSONObject(settings.toString()).put("latitude",wrong);raw.put("solar",invalid);Alarm rejected=Alarm.read(raw);assertTrue(rejected.solarInvalid);assertEquals(0,rejected.next(f.now,f.zone));assertTrue(rejected.json().has("solar"));}raw.put("solar",new JSONObject(settings.toString()).put("fallbackAcknowledged",false));assertTrue(Alarm.read(raw).solarInvalid);raw.put("solar",new JSONObject(settings.toString()).put("unknown",1));assertTrue(Alarm.read(raw).solarInvalid);String original=store.backup().toString();JSONObject backup=store.backup();backup.getJSONArray("alarms").getJSONObject(0).put("solar",new JSONObject(settings.toString()).put("version",2));assertThrows(JSONException.class,()->Backup.validate(backup));assertEquals(original,store.backup().toString());}}
    @Test public void realSolarSaveSkipUndoAndPortableRestoreKeepExactTimeBasis()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm initial=f.load(),draft=Alarm.read(initial.json());draft.solar=solar;Alarm saved=AlarmSkips.edit(f.c,store,draft,initial,true);long chosen=solar.next(saved.hour,saved.minute,saved.days,null,f.now,f.zone,null);assertEquals(chosen,f.deadlines.get(0).longValue());assertEquals(solar.key(),f.load().solar.key());Alarm skipped=AlarmSkips.skip(f.c,saved,chosen);assertEquals(2,skipped.json().getJSONObject("skip").getInt("version"));assertEquals(chosen,skipped.skip.solarAt);assertTrue(skipped.next(f.now,f.zone)>chosen);assertFalse(AlarmSkips.eligible(skipped,chosen,chosen,0,f.zone));Alarm restored=AlarmSkips.undo(f.c,skipped);assertNull(restored.skip);assertEquals(chosen,restored.next(f.now,f.zone));JSONObject portable=store.backup();Backup.validate(portable);Backup.restoreData(store,portable);Alarm reopened=store.alarm(1);assertFalse(reopened.enabled);assertEquals(solar.key(),reopened.solar.key());assertEquals(chosen,reopened.next(f.now,f.zone));}}
    @Test public void changedCoordinatesInvalidateOldSkipAndRejectStaleEditor()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm initial=f.load();initial.solar=solar;store.save(initial);long at=initial.next(f.now,f.zone);Alarm skipped=AlarmSkips.skip(f.c,initial,at),draft=Alarm.read(skipped.json());draft.solar=new SunriseSchedule(51.5,-.12,0,true);Alarm saved=AlarmSkips.edit(f.c,store,draft,skipped,true);assertNull(saved.skip);assertFalse(AlarmSkips.eligible(saved,at,at,0,f.zone));assertThrows(AlarmSkips.Changed.class,()->AlarmSkips.edit(f.c,store,Alarm.read(skipped.json()),skipped,true));JSONObject forged=saved.json().put("skip",skipped.json().getJSONObject("skip"));assertTrue(Alarm.read(forged).skipInvalid);assertEquals(saved.solar.key(),f.load().solar.key());}}
    @Test public void malformedFrozenSolarDeadlineAndMixedClockSkipRemainInvalid()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){Alarm a=f.load();a.solar=solar;long at=a.next(f.now,f.zone);a.skip=new AlarmSkip("11111111-1111-4111-8111-111111111111",Instant.ofEpochMilli(at).atZone(f.zone).toLocalDate(),a.hour,a.minute,a.days,f.zone.getId(),at,solar.key());JSONObject raw=a.json();assertFalse(Alarm.read(raw).skipInvalid);for(Object wrong:new Object[]{at+60000,Double.valueOf(at),""+at,JSONObject.NULL}){JSONObject bad=new JSONObject(raw.toString());bad.getJSONObject("skip").put("solarAt",wrong);assertTrue(Alarm.read(bad).skipInvalid);}JSONObject local=new JSONObject(raw.toString());local.remove("solar");assertTrue(Alarm.read(local).skipInvalid);local.getJSONObject("skip").put("solarAt",0).put("solarKey","");assertTrue(Alarm.read(local).skipInvalid);JSONObject versionOne=new JSONObject(raw.toString());versionOne.put("skip",AlarmSkipJson.encode(new AlarmSkip(a.skip.nonce,a.skip.date,a.hour,a.minute,a.days,"UTC")));assertTrue(Alarm.read(versionOne).skipInvalid);}}
    @Test public void calendarEarlySkipOwnsComputedSolarBaseAndExpiresAtActualAdjustedDeadline()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){String name="solar-calendar-"+UUID.randomUUID();java.util.function.Function<Context,SharedPreferences> old=CalendarSettings.factory;CalendarPolicy.Snapshot previous=CalendarAlarms.snapshot;try{CalendarSettings.factory=context->context.getSharedPreferences(name,Context.MODE_PRIVATE);CalendarSettings.save(f.c,new CalendarPolicy.Rules(true,Set.of(),Set.of(8L),30,180,"solar-calendar"));Alarm a=f.load();a.solar=solar;store.save(a);long base=a.next(f.now,f.zone),early=base-3600000;LocalDate day=Instant.ofEpochMilli(base).atZone(f.zone).toLocalDate();CalendarAlarms.snapshot=new CalendarPolicy.Snapshot(day.minusDays(1).atStartOfDay(f.zone).toInstant().toEpochMilli(),day.plusDays(15).atStartOfDay(f.zone).toInstant().toEpochMilli(),f.now,f.zone,"solar-calendar",List.of(new CalendarPolicy.Event(8,early+1800000,base+3600000,false)));CalendarPolicy.Plan plan=CalendarAlarms.plan(f.c,a,base,f.now,f.zone);assertEquals(early,plan.deadline);CalendarAlarms.scheduled(f.c,a,plan);assertEquals(base,CalendarAlarms.skipBase(f.c,a,early,f.now,f.zone));Alarm skipped=AlarmSkips.skip(f.c,a,early);assertEquals(base,skipped.skip.solarAt);assertEquals(early,CalendarAlarms.skippedDeadline(f.c,skipped,base));assertTrue(skipped.next(f.now,f.zone)>base);f.now=early+1;assertThrows(AlarmSkips.Changed.class,()->AlarmSkips.undo(f.c,skipped));}finally{CalendarAlarms.snapshot=previous;CalendarSettings.factory=old;f.c.deleteSharedPreferences(name);}}}
}
